import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { kitchenApi } from '../utils/api';
import toast from 'react-hot-toast';

const STATUS_META = {
  confirmed:       { label: 'Navbatda',       color: 'text-blue-400',    border: 'border-blue-500/30',    bg: 'bg-blue-500/10',    dot: 'bg-blue-400',    icon: '⏳' },
  in_preparation:  { label: 'Tayyorlanmoqda', color: 'text-amber-400',   border: 'border-amber-500/30',   bg: 'bg-amber-500/10',   dot: 'bg-amber-400 animate-pulse', icon: '🔥' },
  ready:           { label: 'Tayyor!',         color: 'text-emerald-400', border: 'border-emerald-500/30', bg: 'bg-emerald-500/10', dot: 'bg-emerald-400', icon: '✅' },
};

export default function KitchenView() {
  const { kitchenQueue, refreshKitchen, refreshTables } = useApp();
  const [loadingId, setLoadingId] = useState('');

  async function doAction(fn, id, successMsg) {
    setLoadingId(id);
    try {
      await fn();
      await Promise.all([refreshKitchen(), refreshTables()]);
      toast.success(successMsg);
    } catch (err) {
      toast.error(err.response?.data?.error || 'Xatolik yuz berdi');
    } finally {
      setLoadingId('');
    }
  }

  const { activeOrders = [], commandHistory = [] } = kitchenQueue;
  const waiting     = activeOrders.filter((o) => o.status === 'confirmed');
  const preparing   = activeOrders.filter((o) => o.status === 'in_preparation');
  const ready       = activeOrders.filter((o) => o.status === 'ready');

  return (
    <div className="space-y-6">
      {/* Stats + undo */}
      <div className="flex gap-4 items-start">
        <div className="flex gap-4 flex-1">
          <MiniStat label="Navbatda" value={waiting.length} color="blue" />
          <MiniStat label="Tayyorlanmoqda" value={preparing.length} color="amber" />
          <MiniStat label="Tayyor" value={ready.length} color="emerald" />
        </div>
        <button
          onClick={() => doAction(
            () => kitchenApi.undo().then((r) => { if (!r.success) throw new Error(r.message); }),
            'undo',
            'Oxirgi amal bekor qilindi'
          )}
          disabled={!!loadingId || commandHistory.length === 0}
          className="btn btn-ghost shrink-0"
        >
          ↩ Ortga qaytarish
        </button>
      </div>

      {/* Kanban board */}
      {activeOrders.length === 0 ? (
        <div className="card p-16 text-center">
          <p className="text-5xl mb-4">👨‍🍳</p>
          <p className="text-white font-semibold text-lg">Oshxona bo'sh</p>
          <p className="text-gray-600 text-sm mt-1">Hozircha hech qanday faol buyurtma yo'q</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
          {/* Column: Waiting */}
          <KanbanCol title="Navbatda" count={waiting.length} color="blue" icon="⏳">
            {waiting.map((order) => (
              <OrderCard key={order.id} order={order} meta={STATUS_META.confirmed} loadingId={loadingId}
                actions={[
                  { label: '🔥 Tayroylashni boshlash', cls: 'btn-warning', fn: () => doAction(() => kitchenApi.prepare(order.id), `prep-${order.id}`, 'Tayyorlanish boshlandi') },
                  { label: '✕ Bekor qilish', cls: 'btn-ghost text-red-400 border-red-500/20', fn: () => doAction(() => kitchenApi.cancel(order.id), `cancel-${order.id}`, 'Buyurtma bekor qilindi') },
                ]}
              />
            ))}
          </KanbanCol>

          {/* Column: Preparing */}
          <KanbanCol title="Tayyorlanmoqda" count={preparing.length} color="amber" icon="🔥">
            {preparing.map((order) => (
              <OrderCard key={order.id} order={order} meta={STATUS_META.in_preparation} loadingId={loadingId}
                actions={[
                  { label: '✅ Tayyor deb belgilash', cls: 'btn-success', fn: () => doAction(() => kitchenApi.markReady(order.id), `ready-${order.id}`, 'Buyurtma tayyor!') },
                  { label: '✕ Bekor qilish', cls: 'btn-ghost text-red-400 border-red-500/20', fn: () => doAction(() => kitchenApi.cancel(order.id), `cancel-${order.id}`, 'Buyurtma bekor qilindi') },
                ]}
              />
            ))}
          </KanbanCol>

          {/* Column: Ready */}
          <KanbanCol title="Tayyor" count={ready.length} color="emerald" icon="✅">
            {ready.map((order) => (
              <OrderCard key={order.id} order={order} meta={STATUS_META.ready} loadingId={loadingId}
                actions={[]}
              />
            ))}
          </KanbanCol>
        </div>
      )}

      {/* Command history */}
      {commandHistory.length > 0 && (
        <div className="card p-5">
          <h3 className="text-sm font-semibold text-gray-400 mb-3 flex items-center gap-2">
            <span>📋</span> Amallar tarixi
          </h3>
          <div className="space-y-1.5 max-h-36 overflow-y-auto">
            {[...commandHistory].reverse().map((cmd, i) => (
              <div key={i} className="flex items-center gap-2 text-xs text-gray-500 bg-white/[0.03] rounded-lg px-3 py-2">
                <span className="text-gray-700">#{commandHistory.length - i}</span>
                <span>{cmd}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function MiniStat({ label, value, color }) {
  const c = { blue: 'text-blue-400 border-blue-500/20', amber: 'text-amber-400 border-amber-500/20', emerald: 'text-emerald-400 border-emerald-500/20' };
  return (
    <div className={`card border ${c[color]} px-5 py-3 flex items-center gap-3 flex-1`}>
      <span className={`text-2xl font-bold ${c[color].split(' ')[0]}`}>{value}</span>
      <span className="text-gray-500 text-xs">{label}</span>
    </div>
  );
}

function KanbanCol({ title, count, color, icon, children }) {
  const c = { blue: 'text-blue-400', amber: 'text-amber-400', emerald: 'text-emerald-400' };
  return (
    <div className="card flex flex-col">
      <div className="card-header">
        <div className="flex items-center gap-2">
          <span>{icon}</span>
          <span className="text-white font-semibold text-sm">{title}</span>
        </div>
        <span className={`badge bg-white/5 ${c[color]}`}>{count}</span>
      </div>
      <div className="p-3 space-y-3 flex-1 overflow-y-auto min-h-[100px]">
        {children}
      </div>
    </div>
  );
}

function OrderCard({ order, meta, actions, loadingId }) {
  const isLoading = actions.some((a, i) => loadingId === `${['prep', 'ready', 'cancel'][i]}-${order.id}`);
  return (
    <div className={`rounded-xl border ${meta.border} ${meta.bg} p-3.5`}>
